-- Zukkolab demo kontenti (statik). Dinamik qism (guruhlar, slotlar, lidlar) — select public.reset_demo_data().
-- Barcha maʼlumotlar toʻqima. Qayta ishga tushirish xavfsiz: kontent jadvallari tozalanib qayta toʻldiriladi.

begin;

delete from public.bookings; delete from public.students; delete from public.lead_events; delete from public.leads;
delete from public.test_attempts; delete from public.trial_slots; delete from public.groups;
delete from public.test_questions; delete from public.testimonials; delete from public.faq;
delete from public.teachers; delete from public.courses; delete from public.branches; delete from public.directions;









on conflict (key) do nothing;

-- Guruhlar, slotlar, demo lidlar, bronlar va reklama xarajatlari — bugungi sanaga nisbatan.
select public.reset_demo_data();

commit;
