insert into public.branches (slug, name_uz, name_ru, name_en, address_uz, address_ru, address_en, landmark_uz, landmark_ru, landmark_en, lat, lng, phone, working_hours_uz, working_hours_ru, working_hours_en, photo_url, sort) values
  ('chilonzor', 'Chilonzor', 'Чиланзар', 'Chilanzar', 'Chilonzor tumani, Bunyodkor shoh koʻchasi, 12-uy', 'Чиланзарский район, проспект Бунёдкор, 12', '12 Bunyodkor Avenue, Chilanzar district', 'Novza metro bekati yonida', 'Рядом со станцией метро Новза', 'Next to Novza metro station', 41.2826, 69.2125, '+998712001010', 'Du–Sh: 09:00–20:00, Ya: dam olish', 'Пн–Сб: 09:00–20:00, Вс: выходной', 'Mon–Sat: 9:00–20:00, Sun: closed', '/images/branches/chilonzor.webp', 1),
  ('yunusobod', 'Yunusobod', 'Юнусабад', 'Yunusabad', 'Yunusobod tumani, Amir Temur shoh koʻchasi, 108-uy', 'Юнусабадский район, проспект Амира Темура, 108', '108 Amir Temur Avenue, Yunusabad district', 'Yunusobod metro bekati, 3-chiqish', 'Станция метро Юнусабад, выход 3', 'Yunusabad metro station, exit 3', 41.3647, 69.287, '+998712002020', 'Du–Sh: 09:00–20:00, Ya: dam olish', 'Пн–Сб: 09:00–20:00, Вс: выходной', 'Mon–Sat: 9:00–20:00, Sun: closed', '/images/branches/yunusobod.webp', 2),
  ('mirzo-ulugbek', 'Mirzo Ulugʻbek', 'Мирзо-Улугбек', 'Mirzo Ulugbek', 'Mirzo Ulugʻbek tumani, Buyuk Ipak Yoʻli koʻchasi, 45-uy', 'Мирзо-Улугбекский район, улица Буюк Ипак Йули, 45', '45 Buyuk Ipak Yuli Street, Mirzo Ulugbek district', 'Buyuk Ipak Yoʻli metro bekati qarshisida', 'Напротив станции метро Буюк Ипак Йули', 'Opposite Buyuk Ipak Yuli metro station', 41.326, 69.327, '+998712003030', 'Du–Sh: 09:00–20:00, Ya: dam olish', 'Пн–Сб: 09:00–20:00, Вс: выходной', 'Mon–Sat: 9:00–20:00, Sun: closed', '/images/branches/mirzo-ulugbek.webp', 3);
insert into public.courses (direction_id, slug, title_uz, title_ru, title_en, description_uz, description_ru, description_en, program_uz, program_ru, program_en, level_from, level_to, age_group, duration_months, lessons_per_week, lesson_minutes, price_monthly, is_featured, sort) values
  ((select id from public.directions where slug = 'english'), 'english-kids', 'Bolalar uchun ingliz tili', 'Английский для детей', 'English for Kids', '7–11 yoshli bolalar uchun oʻyin, qoʻshiq va multfilmlar orqali ingliz tili. Har darsda gapirish amaliyoti.', 'Английский для детей 7–11 лет через игры, песни и мультфильмы. Разговорная практика на каждом уроке.', 'English for children aged 7–11 through games, songs and cartoons. Speaking practice in every lesson.', array['Alifbo va talaffuz', 'Kundalik soʻzlar: oila, maktab, hayvonlar', 'Oddiy jumlalar tuzish', 'Qoʻshiq va rolli oʻyinlar']::text[], array['Алфавит и произношение', 'Повседневные слова: семья, школа, животные', 'Простые предложения', 'Песни и ролевые игры']::text[], array['Alphabet and pronunciation', 'Everyday words: family, school, animals', 'Building simple sentences', 'Songs and role plays']::text[], 1, 2, 'kids', 9, 3, 60, 600000, false, 1),
  ((select id from public.directions where slug = 'english'), 'general-english', 'General English', 'General English', 'General English', 'Boshlangʻichdan B2 gacha: grammatika, lugʻat va erkin muloqot. Har 2 oyda daraja nazorati.', 'С нуля до B2: грамматика, лексика и свободное общение. Контроль уровня каждые 2 месяца.', 'From beginner to B2: grammar, vocabulary and fluent conversation. Level check every 2 months.', array['Grammatika asoslari', 'Soʻz boyligi: 1500+ soʻz', 'Speaking club har hafta', 'Daraja imtihoni']::text[], array['Основы грамматики', 'Словарный запас: 1500+ слов', 'Speaking club каждую неделю', 'Экзамен на уровень']::text[], array['Grammar foundations', 'Vocabulary: 1,500+ words', 'Weekly speaking club', 'Level exam']::text[], 1, 3, 'teens', 6, 3, 90, 750000, true, 2),
  ((select id from public.directions where slug = 'english'), 'ielts-intensive', 'IELTS Intensive', 'IELTS Intensive', 'IELTS Intensive', 'B1 dan boshlab IELTS 7.0+ ga tayyorlov: 4 ta koʻnikma, haftalik mock test va individual feedback.', 'Подготовка к IELTS 7.0+ с уровня B1: 4 навыка, еженедельный mock-тест и индивидуальный разбор.', 'IELTS 7.0+ preparation from B1: all 4 skills, weekly mock test and individual feedback.', array['Listening va Reading strategiyalari', 'Writing Task 1 va 2', 'Speaking: Part 1–3', 'Har hafta mock test']::text[], array['Стратегии Listening и Reading', 'Writing Task 1 и 2', 'Speaking: Part 1–3', 'Mock-тест каждую неделю']::text[], array['Listening and Reading strategies', 'Writing Task 1 and 2', 'Speaking: Parts 1–3', 'Weekly mock test']::text[], 2, 4, 'teens', 4, 5, 90, 1100000, true, 3),
  ((select id from public.directions where slug = 'russian'), 'russian-kids', 'Bolalar uchun rus tili', 'Русский для детей', 'Russian for Kids', 'Maktabga tayyorgarlik va 1–4-sinf oʻquvchilari uchun rus tili: oʻqish, yozish va soʻzlashuv.', 'Русский язык для дошкольников и учеников 1–4 классов: чтение, письмо и разговор.', 'Russian for preschoolers and grades 1–4: reading, writing and speaking.', array['Alifbo va oʻqish', 'Yozuv va imlo', 'Soʻzlashuv mavzulari', 'Ertak va sheʼrlar']::text[], array['Алфавит и чтение', 'Письмо и орфография', 'Разговорные темы', 'Сказки и стихи']::text[], array['Alphabet and reading', 'Writing and spelling', 'Conversation topics', 'Fairy tales and poems']::text[], 1, 2, 'kids', 9, 3, 60, 550000, false, 4),
  ((select id from public.directions where slug = 'russian'), 'russian-general', 'Rus tili: soʻzlashuv va grammatika', 'Русский язык: разговор и грамматика', 'Russian: Speaking and Grammar', 'Oʻsmirlar va kattalar uchun: kelishiklar, feʼllar va erkin muloqot. Ish va oʻqish uchun rus tili.', 'Для подростков и взрослых: падежи, глаголы и свободное общение. Русский для учёбы и работы.', 'For teens and adults: cases, verbs and fluent conversation. Russian for study and work.', array['Kelishiklar tizimi', 'Feʼl turlari va zamonlar', 'Ish suhbati va hujjatlar', 'Erkin muloqot klubi']::text[], array['Система падежей', 'Виды глагола и времена', 'Деловое общение и документы', 'Разговорный клуб']::text[], array['The case system', 'Verb aspects and tenses', 'Business talk and documents', 'Conversation club']::text[], 1, 4, 'adults', 6, 3, 90, 650000, false, 5),
  ((select id from public.directions where slug = 'math'), 'math-school', 'Maktab matematikasi', 'Школьная математика', 'School Math', '5–9-sinflar uchun: mavzularni tushunib oʻrganish, baholarni oshirish va nazorat ishlariga tayyorgarlik.', 'Для 5–9 классов: понимание тем, рост оценок и подготовка к контрольным.', 'For grades 5–9: understanding topics, better grades and test preparation.', array['Kasrlar va foizlar', 'Tenglamalar', 'Geometriya asoslari', 'Nazorat ishiga tayyorgarlik']::text[], array['Дроби и проценты', 'Уравнения', 'Основы геометрии', 'Подготовка к контрольным']::text[], array['Fractions and percentages', 'Equations', 'Geometry basics', 'Test preparation']::text[], 1, 3, 'teens', 9, 3, 90, 600000, false, 6),
  ((select id from public.directions where slug = 'math'), 'math-olympiad', 'Olimpiada matematikasi', 'Олимпиадная математика', 'Olympiad Math', 'Kuchli oʻquvchilar uchun: nostandart masalalar, kombinatorika va sonlar nazariyasi. Tuman va shahar olimpiadalariga tayyorlov.', 'Для сильных учеников: нестандартные задачи, комбинаторика и теория чисел. Подготовка к районным и городским олимпиадам.', 'For strong students: non-standard problems, combinatorics and number theory. Preparation for district and city olympiads.', array['Sonlar nazariyasi', 'Kombinatorika', 'Olimpiada geometriyasi', 'Har oy sinov olimpiadasi']::text[], array['Теория чисел', 'Комбинаторика', 'Олимпиадная геометрия', 'Пробная олимпиада каждый месяц']::text[], array['Number theory', 'Combinatorics', 'Olympiad geometry', 'Monthly mock olympiad']::text[], 3, 4, 'teens', 9, 2, 120, 800000, true, 7),
  ((select id from public.directions where slug = 'abiturient'), 'abiturient-dtm', 'Abituriyent: DTM tayyorlov', 'Абитуриент: подготовка к DTM', 'University Entrance Prep', 'Oliy oʻquv yurtiga kirish testlariga tayyorlov: matematika va asosiy fan, haftalik DTM formatidagi sinov testlari.', 'Подготовка к вступительным тестам в вуз: математика и профильный предмет, еженедельные пробные тесты в формате DTM.', 'Preparation for university entrance tests: math and a core subject, weekly mock tests in DTM format.', array['Matematika: barcha mavzular', 'Asosiy fan boʻyicha chuqur tayyorlov', 'Haftalik DTM sinov testi', 'Vaqtni boshqarish strategiyasi']::text[], array['Математика: все темы', 'Углублённая подготовка по профильному предмету', 'Еженедельный пробный тест DTM', 'Стратегия управления временем']::text[], array['Math: all topics', 'In-depth core subject preparation', 'Weekly DTM mock test', 'Time management strategy']::text[], 1, 4, 'teens', 8, 5, 120, 900000, true, 8),
  ((select id from public.directions where slug = 'it'), 'python-kids', 'Bolalar uchun Python', 'Python для детей', 'Python for Kids', '9–13 yoshli bolalar uchun: oʻyinlar yaratish orqali dasturlash mantiqini oʻrganish.', 'Для детей 9–13 лет: изучаем логику программирования, создавая игры.', 'For kids aged 9–13: learning programming logic by building games.', array['Scratchʼdan Pythonʼga', 'Oʻzgaruvchilar va sikllar', 'Birinchi oʻyin', 'Yakuniy loyiha taqdimoti']::text[], array['От Scratch к Python', 'Переменные и циклы', 'Первая игра', 'Защита итогового проекта']::text[], array['From Scratch to Python', 'Variables and loops', 'Your first game', 'Final project demo']::text[], 1, 4, 'kids', 6, 2, 90, 700000, false, 9),
  ((select id from public.directions where slug = 'it'), 'frontend', 'Frontend dasturlash', 'Frontend-разработка', 'Frontend Development', 'HTML, CSS, JavaScript va React: noldan portfolio bilan ishga tayyor darajagacha.', 'HTML, CSS, JavaScript и React: с нуля до готового к работе уровня с портфолио.', 'HTML, CSS, JavaScript and React: from zero to job-ready with a portfolio.', array['HTML va CSS', 'JavaScript asoslari', 'React', 'Portfolio uchun 3 ta loyiha']::text[], array['HTML и CSS', 'Основы JavaScript', 'React', '3 проекта для портфолио']::text[], array['HTML and CSS', 'JavaScript basics', 'React', '3 portfolio projects']::text[], 1, 4, 'adults', 8, 3, 120, 1200000, true, 10),
  ((select id from public.directions where slug = 'it'), 'backend-python', 'Backend: Python va Django', 'Backend: Python и Django', 'Backend: Python and Django', 'Server dasturlash: Python, maʼlumotlar bazasi, API va deploy. Real loyiha jamoada.', 'Серверная разработка: Python, базы данных, API и деплой. Реальный проект в команде.', 'Server-side development: Python, databases, APIs and deployment. A real team project.', array['Python asoslari', 'SQL va PostgreSQL', 'Django va REST API', 'Jamoaviy loyiha']::text[], array['Основы Python', 'SQL и PostgreSQL', 'Django и REST API', 'Командный проект']::text[], array['Python basics', 'SQL and PostgreSQL', 'Django and REST APIs', 'Team project']::text[], 1, 4, 'adults', 8, 3, 120, 1200000, false, 11),
  ((select id from public.directions where slug = 'it'), 'ui-ux-design', 'UI/UX dizayn', 'UI/UX-дизайн', 'UI/UX Design', 'Figmaʼda ilova va saytlar dizayni: foydalanuvchi tadqiqoti, prototip va portfolio.', 'Дизайн приложений и сайтов в Figma: исследование пользователей, прототип и портфолио.', 'App and web design in Figma: user research, prototyping and a portfolio.', array['Dizayn asoslari va kompozitsiya', 'Figma', 'UX tadqiqot va prototip', 'Portfolio keys']::text[], array['Основы дизайна и композиция', 'Figma', 'UX-исследование и прототип', 'Кейс для портфолио']::text[], array['Design basics and composition', 'Figma', 'UX research and prototyping', 'Portfolio case study']::text[], 1, 4, 'adults', 5, 3, 120, 1000000, false, 12);
insert into public.teachers (full_name, photo_url, direction_id, experience_years, certificates, bio_uz, bio_ru, bio_en, sort) values
  ('Dilnoza Karimova', '/images/teachers/dilnoza.webp', (select id from public.directions where slug = 'english'), 7, array['IELTS 8.5', 'CELTA']::text[], 'IELTS boʻyicha 300 dan ortiq oʻquvchini 7.0+ natijaga olib chiqqan. Darslarida koʻproq gapirtiradi.', 'Подготовила более 300 учеников к IELTS 7.0+. На уроках больше всего говорят ученики.', 'Has taken 300+ students to IELTS 7.0+. In her lessons, students do most of the talking.', 1),
  ('Jasur Toshmatov', '/images/teachers/jasur.webp', (select id from public.directions where slug = 'english'), 5, array['IELTS 8.0', 'TKT']::text[], 'Bolalar va oʻsmirlar bilan ishlaydi. Oʻyin va loyihalar orqali oʻqitadi.', 'Работает с детьми и подростками. Учит через игры и проекты.', 'Works with kids and teens. Teaches through games and projects.', 2),
  ('Svetlana Kim', '/images/teachers/svetlana.webp', (select id from public.directions where slug = 'russian'), 12, array['Rus filologiyasi magistri']::text[], '12 yillik tajriba. Grammatikani jadval va misollar bilan oson tushuntiradi.', '12 лет опыта. Объясняет грамматику просто — через схемы и примеры.', '12 years of experience. Makes grammar simple with charts and examples.', 3),
  ('Bekzod Yusupov', '/images/teachers/bekzod.webp', (select id from public.directions where slug = 'math'), 9, array['Respublika olimpiadasi gʻolibi', 'Olimpiada murabbiyi']::text[], 'Oʻquvchilari shahar olimpiadalarida 40 dan ortiq sovrin olgan.', 'Его ученики взяли более 40 призов на городских олимпиадах.', 'His students have won 40+ prizes at city olympiads.', 4),
  ('Malika Ergasheva', '/images/teachers/malika.webp', (select id from public.directions where slug = 'abiturient'), 8, array['DTM 189 ball', 'Pedagogika magistri']::text[], 'Abituriyentlarni DTM formatida tayyorlaydi; har hafta sinov testi va tahlil.', 'Готовит абитуриентов в формате DTM: еженедельный пробный тест и разбор.', 'Prepares applicants in DTM format: a weekly mock test with review.', 5),
  ('Sardor Aliyev', '/images/teachers/sardor.webp', (select id from public.directions where slug = 'it'), 6, array['Senior Frontend Developer', 'React']::text[], 'Mahalliy IT kompaniyada senior frontend dasturchi. Darsda real loyihalar ustida ishlaydi.', 'Senior frontend-разработчик в местной IT-компании. На уроках — реальные проекты.', 'Senior frontend developer at a local IT company. Lessons are built around real projects.', 6),
  ('Nodira Saidova', '/images/teachers/nodira.webp', (select id from public.directions where slug = 'it'), 5, array['Product Designer', 'Google UX Certificate']::text[], 'Mahsulot dizayneri. 20 dan ortiq ilova va sayt dizaynini yaratgan.', 'Продуктовый дизайнер. Создала дизайн более 20 приложений и сайтов.', 'Product designer. Has designed 20+ apps and websites.', 7),
  ('Timur Abdullayev', '/images/teachers/timur.webp', (select id from public.directions where slug = 'it'), 7, array['Python Developer', 'Django']::text[], 'Backend dasturchi va bolalar uchun Python oʻqituvchisi. Murakkabni oddiy tilda tushuntiradi.', 'Backend-разработчик и преподаватель Python для детей. Объясняет сложное простым языком.', 'Backend developer and Python teacher for kids. Explains complex things in plain words.', 8);
insert into public.faq (question_uz, question_ru, question_en, answer_uz, answer_ru, answer_en, sort) values
  ('Sinov darsi haqiqatan bepulmi?', 'Пробный урок действительно бесплатный?', 'Is the trial lesson really free?', 'Ha, birinchi sinov darsi toʻliq bepul va hech qanday majburiyat yoʻq. Darsdan keyin oʻzingiz qaror qilasiz.', 'Да, первый пробный урок полностью бесплатный и ни к чему не обязывает. После урока вы решаете сами.', 'Yes, the first trial lesson is completely free with no obligation. You decide after the lesson.', 1),
  ('Narxlar qancha?', 'Сколько стоит обучение?', 'How much do courses cost?', 'Kurslar oyiga 550 000 soʻmdan 1 200 000 soʻmgacha. Aniq narx kurs sahifasida koʻrsatilgan.', 'Курсы стоят от 550 000 до 1 200 000 сумов в месяц. Точная цена указана на странице курса.', 'Courses cost from 550,000 to 1,200,000 UZS per month. The exact price is on each course page.', 2),
  ('Boʻlib toʻlash mumkinmi?', 'Можно ли платить частями?', 'Can I pay in instalments?', 'Ha, toʻlov har oy amalga oshiriladi. 3 oy uchun oldindan toʻlasangiz — 10% chegirma.', 'Да, оплата помесячная. При оплате за 3 месяца вперёд — скидка 10%.', 'Yes, payment is monthly. Pay for 3 months upfront and get 10% off.', 3),
  ('Chegirmalar bormi?', 'Есть ли скидки?', 'Are there any discounts?', 'Aka-uka va opa-singillar uchun ikkinchi farzandga 15% chegirma. Doʻstini olib kelgan oʻquvchiga 1 hafta bepul.', 'Для братьев и сестёр — скидка 15% на второго ребёнка. Привёл друга — неделя обучения бесплатно.', 'Siblings get 15% off for the second child. Bring a friend and get one week free.', 4),
  ('Guruhda nechta oʻquvchi boʻladi?', 'Сколько учеников в группе?', 'How many students are in a group?', 'Guruhlarda 8 tadan 12 tagacha oʻquvchi. Bolalar guruhlarida — 10 tagacha.', 'В группах от 8 до 12 учеников. В детских группах — до 10.', 'Groups have 8 to 12 students. Kids'' groups have up to 10.', 5),
  ('Agar natija boʻlmasa-chi?', 'А если не будет результата?', 'What if I don''t see results?', 'Birinchi oy oxirida oʻquvchi darajasi tekshiriladi. Natija boʻlmasa, keyingi oy bepul.', 'В конце первого месяца проверяем уровень. Если результата нет — следующий месяц бесплатно.', 'We check the student''s level at the end of the first month. No progress means the next month is free.', 6),
  ('Darslar qaysi tilda oʻtadi?', 'На каком языке проходят занятия?', 'What language are classes taught in?', 'Tushuntirishlar oʻzbek yoki rus tilida — guruh tanlovingizga qarab. Til kurslarida asosiy amaliyot oʻqitilayotgan tilda.', 'Объяснения на узбекском или русском — по выбору группы. На языковых курсах основная практика — на изучаемом языке.', 'Explanations are in Uzbek or Russian depending on the group. Language courses practise mostly in the target language.', 7),
  ('Darsni oʻtkazib yuborsam nima boʻladi?', 'Что если я пропущу урок?', 'What if I miss a class?', 'Har bir dars yozib olinadi va Telegram guruhga yuboriladi. Oʻqituvchi bilan qoʻshimcha konsultatsiya ham bor.', 'Каждый урок записывается и отправляется в Telegram-группу. Есть дополнительные консультации с преподавателем.', 'Every lesson is recorded and shared in the Telegram group. Extra consultations with the teacher are available.', 8),
  ('Qaysi filial menga yaqin?', 'Какой филиал ближе ко мне?', 'Which branch is closest to me?', 'Bizda 3 ta filial bor: Chilonzor (Novza metro), Yunusobod (Yunusobod metro) va Mirzo Ulugʻbek (Buyuk Ipak Yoʻli metro).', 'У нас 3 филиала: Чиланзар (метро Новза), Юнусабад (метро Юнусабад) и Мирзо-Улугбек (метро Буюк Ипак Йули).', 'We have 3 branches: Chilanzar (Novza metro), Yunusabad (Yunusabad metro) and Mirzo Ulugbek (Buyuk Ipak Yuli metro).', 9),
  ('Necha yoshdan qabul qilasiz?', 'С какого возраста принимаете?', 'From what age do you accept students?', '7 yoshdan boshlab. 7–11 yoshli bolalar uchun alohida oʻyin uslubidagi kurslar bor.', 'С 7 лет. Для детей 7–11 лет есть отдельные курсы в игровом формате.', 'From age 7. Children aged 7–11 have separate game-based courses.', 10);
insert into public.testimonials (name, direction_id, achievement_uz, achievement_ru, achievement_en, text_uz, text_ru, text_en, photo_url, is_demo, sort) values
  ('Aziz, 17', (select id from public.directions where slug = 'english'), 'IELTS 7.5', 'IELTS 7.5', 'IELTS 7.5', '4 oyda 5.5 dan 7.5 ga chiqdim. Har hafta mock test eng koʻp yordam berdi.', 'За 4 месяца поднялся с 5.5 до 7.5. Больше всего помогли еженедельные mock-тесты.', 'I went from 5.5 to 7.5 in 4 months. The weekly mock tests helped the most.', '/images/testimonials/1.webp', true, 1),
  ('Madina, 15', (select id from public.directions where slug = 'math'), 'Shahar olimpiadasi, 2-oʻrin', 'Городская олимпиада, 2 место', 'City olympiad, 2nd place', 'Oldin olimpiada masalalaridan qoʻrqardim, endi ularni yechish eng qiziq mashgʻulotim.', 'Раньше боялась олимпиадных задач, теперь это моё любимое занятие.', 'I used to be afraid of olympiad problems — now solving them is my favourite thing.', '/images/testimonials/2.webp', true, 2),
  ('Sevara opa (ota-ona)', (select id from public.directions where slug = 'russian'), 'Oʻgʻli 3 oyda erkin gapira boshladi', 'Сын за 3 месяца заговорил свободно', 'Her son speaks freely after 3 months', 'Oʻgʻlim maktabda rus tilidan qiynalardi. 3 oyda baholari 5 ga chiqdi, endi oʻzi kitob oʻqiydi.', 'Сыну было тяжело с русским в школе. За 3 месяца оценки выросли до пятёрок, теперь он сам читает книги.', 'My son struggled with Russian at school. In 3 months his grades went up to top marks and now he reads books himself.', '/images/testimonials/3.webp', true, 3),
  ('Javohir, 22', (select id from public.directions where slug = 'it'), 'Junior Frontend dasturchi', 'Junior Frontend-разработчик', 'Junior Frontend Developer', 'Kurs tugashidan oldin portfoliodagi loyiham bilan ishga qabul qilindim.', 'Меня взяли на работу ещё до окончания курса — благодаря проекту из портфолио.', 'I got hired before the course ended thanks to my portfolio project.', '/images/testimonials/4.webp', true, 4),
  ('Shahzoda, 18', (select id from public.directions where slug = 'abiturient'), 'DTM: 184 ball, grant', 'DTM: 184 балла, грант', 'DTM: 184 points, scholarship', 'Haftalik sinov testlari imtihonda hayajonni yoʻqotdi. Grant asosida oʻqishga kirdim.', 'Еженедельные пробные тесты сняли волнение на экзамене. Поступила на грант.', 'Weekly mock tests took away my exam nerves. I got into university on a scholarship.', '/images/testimonials/5.webp', true, 5),
  ('Bobur, 10', (select id from public.directions where slug = 'it'), 'Birinchi oʻyinini yaratdi', 'Создал свою первую игру', 'Built his first game', 'Pythonʼda oʻzim oʻyin yasadim va uni doʻstlarimga koʻrsatdim!', 'Я сам сделал игру на Python и показал её друзьям!', 'I made my own game in Python and showed it to my friends!', '/images/testimonials/6.webp', true, 6);
